import { ContextMenu, ContextMenuContent, ContextMenuItem, ContextMenuLinkItem, ContextMenuSeparator, ContextMenuTrigger } from "@kitora/ui/context-menu"

export function ContextMenuBackdropArrowAndLink() {
  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>
        <div className="grid h-32 w-full max-w-md place-items-center rounded-md border border-dashed border-border-strong bg-muted/40 text-sm text-muted-foreground">
          Right-click here
        </div>
      </ContextMenuTrigger>
      <ContextMenuContent backdrop arrow side="bottom" align="center" sideOffset={8}>
        <ContextMenuItem>
          <Copy /> Copy
        </ContextMenuItem>
        <ContextMenuLinkItem href="/components/context-menu">Open the docs</ContextMenuLinkItem>
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive">Delete</ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  )
}
