import { CheckIcon, ChevronRightIcon, CircleIcon } from "lucide-react"
import { ContextMenu } from "@kitora/primitives/react"

const POPUP = "z-50 min-w-44 rounded-lg bg-popover p-1 text-sm text-popover-foreground shadow-md ring-1 ring-foreground/10 outline-none"
const ITEM = "flex cursor-default items-center gap-2 rounded-md px-2 py-1.5 outline-none select-none data-disabled:opacity-50 data-highlighted:bg-accent data-highlighted:text-accent-foreground"

/** The popup of the menu or a submenu, placed beside the point (or the submenu trigger) it opened at. */
function Popup({ children }: { children: ReactNode }) {
  return (
    <ContextMenu.Portal>
      <ContextMenu.Positioner side="inline-end" align="start" className="isolate z-50 outline-none">
        <ContextMenu.Popup className={POPUP}>{children}</ContextMenu.Popup>
      </ContextMenu.Positioner>
    </ContextMenu.Portal>
  )
}

/** A context menu built from the primitives' \`ContextMenu\` parts only: right-click (or Shift+F10) in the box. */
export function ContextMenuBuildYourOwn({ open, onOpenChange }: { open?: boolean; onOpenChange?: (open: boolean) => void }) {
  const [rulers, setRulers] = useState(false)
  const [sort, setSort] = useState("name")
  return (
    <ContextMenu.Root open={open} onOpenChange={(next) => onOpenChange?.(next)}>
      <ContextMenu.Trigger
        tabIndex={0}
        aria-label="Canvas"
        className="flex h-36 w-full max-w-sm items-center justify-center rounded-lg border border-dashed border-border text-sm text-muted-foreground select-none"
      >
        Right-click here
      </ContextMenu.Trigger>
      <Popup>
        <ContextMenu.Group>
          <ContextMenu.GroupLabel className="px-2 py-1 text-xs font-medium text-muted-foreground">Edit</ContextMenu.GroupLabel>
          <ContextMenu.Item className={ITEM}>
            Copy <span className="ms-auto text-xs text-muted-foreground">⌘C</span>
          </ContextMenu.Item>
          <ContextMenu.Item className={ITEM}>Paste</ContextMenu.Item>
          <ContextMenu.Item className={ITEM} disabled>
            Delete
          </ContextMenu.Item>
        </ContextMenu.Group>
        <ContextMenu.Separator className="-mx-1 my-1 h-px bg-border" />
        <ContextMenu.CheckboxItem className={ITEM} checked={rulers} onCheckedChange={setRulers}>
          <span className="flex size-4 items-center justify-center">
            <ContextMenu.CheckboxItemIndicator>
              <CheckIcon className="size-4" />
            </ContextMenu.CheckboxItemIndicator>
          </span>
          Show rulers
        </ContextMenu.CheckboxItem>
        <ContextMenu.RadioGroup value={sort} onValueChange={(next) => setSort(next as string)}>
          {["name", "date"].map((value) => (
            <ContextMenu.RadioItem key={value} value={value} className={ITEM}>
              <span className="flex size-4 items-center justify-center">
                <ContextMenu.RadioItemIndicator>
                  <CircleIcon className="size-2 fill-current" />
                </ContextMenu.RadioItemIndicator>
              </span>
              {value === "name" ? "Sort by name" : "Sort by date"}
            </ContextMenu.RadioItem>
          ))}
        </ContextMenu.RadioGroup>
        <ContextMenu.Separator className="-mx-1 my-1 h-px bg-border" />
        <ContextMenu.SubmenuRoot>
          <ContextMenu.SubmenuTrigger className={ITEM}>
            Share
            <ChevronRightIcon className="ms-auto size-4 rtl:rotate-180" />
          </ContextMenu.SubmenuTrigger>
          <Popup>
            <ContextMenu.Item className={ITEM}>Email link</ContextMenu.Item>
            <ContextMenu.Item className={ITEM}>Copy link</ContextMenu.Item>
          </Popup>
        </ContextMenu.SubmenuRoot>
      </Popup>
    </ContextMenu.Root>
  )
}
