export function ContextMenuComposeFileCard() {
  return (
    <div className="flex flex-wrap items-center justify-center gap-3">
      <ContextMenu>
        <ContextMenuTrigger asChild>
          <Card className="w-full max-w-sm cursor-context-menu">
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                roadmap-q4.pdf
                <Badge variant="secondary">Shared</Badge>
              </CardTitle>
              <CardDescription>Right-click (or long-press) for actions.</CardDescription>
            </CardHeader>
          </Card>
        </ContextMenuTrigger>
        <ContextMenuContent>
          <ContextMenuItem>
            <Pencil />
            Rename
            <ContextMenuShortcut>F2</ContextMenuShortcut>
          </ContextMenuItem>
          <ContextMenuItem>
            <Copy />
            Duplicate
          </ContextMenuItem>
          <ContextMenuSeparator />
          <ContextMenuItem className="text-destructive">
            <Trash2 />
            Delete
          </ContextMenuItem>
        </ContextMenuContent>
      </ContextMenu>
    </div>
  )
}
